554	  async function logPluginMutationActivity(
555	    req: Request,
556	    action: string,
557	    entityId: string,
558	    details: Record<string, unknown>,
559	  ): Promise<void> {
560	    const companyIds = await resolvePluginAuditCompanyIds(req);
561	    if (companyIds.length === 0) return;
562	
563	    const actor = getActorInfo(req);
564	    await Promise.all(companyIds.map((companyId) =>
565	      logActivity(db, {
566	        companyId,
567	        actorType: actor.actorType,
568	        actorId: actor.actorId,
569	        agentId: actor.agentId,
570	        runId: actor.runId,
571	        action,
572	        entityType: "plugin",
573	        entityId,
574	        details,
575	      })));
576	  }
