1881	  /**
1882	   * GET /api/plugins/:pluginId/bridge/stream/:channel
1883	   *
1884	   * TODO(cloudflare): SSE streaming via res.write() is Express/Node-specific.
1885	   * For Workers compatibility this route must be rewritten using the
1886	   * TransformStream / ReadableStream API. Keep the existing Express code path.
1887	   */
1888	  router.get("/plugins/:pluginId/bridge/stream/:channel", async (req, res) => {
1889	    assertBoardOrgAccess(req);
1890	
1891	    if (!bridgeDeps?.streamBus) {
1892	      res.status(501).json({ error: "Plugin stream bridge is not enabled" });
1893	      return;
1894	    }
1895	
1896	    const { pluginId, channel } = req.params;
1897	    const companyId = req.query.companyId as string | undefined;
1898	
1899	    if (!companyId) {
1900	      res.status(400).json({ error: '"companyId" query parameter is required' });
1901	      return;
1902	    }
1903	
1904	    const plugin = await resolvePlugin(registry, pluginId);
1905	    if (!plugin) {
1906	      res.status(404).json({ error: "Plugin not found" });
1907	      return;
1908	    }
1909	
1910	    assertCompanyAccess(req, companyId);
1911	
1912	    res.writeHead(200, {
1913	      "Content-Type": "text/event-stream",
1914	      "Cache-Control": "no-cache",
1915	      "Connection": "keep-alive",
1916	      "X-Accel-Buffering": "no",
1917	    });
1918	    res.flushHeaders();
1919	
1920	    res.write(":ok\n\n");
1921	
1922	    let unsubscribed = false;
1923	    const safeUnsubscribe = () => {
1924	      if (!unsubscribed) {
1925	        unsubscribed = true;
1926	        unsubscribe();
1927	      }
1928	    };
1929	
1930	    const unsubscribe = bridgeDeps.streamBus.subscribe(
1931	      plugin.id,
1932	      channel,
1933	      companyId,
1934	      (event, eventType) => {
1935	        if (unsubscribed || !res.writable) return;
1936	        try {
1937	          if (eventType !== "message") {
1938	            res.write(`event: ${eventType}\n`);
1939	          }
1940	          res.write(`data: ${JSON.stringify(event)}\n\n`);
1941	        } catch {
1942	          safeUnsubscribe();
1943	        }
1944	      },
1945	    );
1946	
1947	    req.on("close", safeUnsubscribe);
1948	    res.on("error", safeUnsubscribe);
1949	  });
