1951	  /**
1952	   * router.use /plugins/:pluginId/api
1953	   *
1954	   * TODO(cloudflare): This scoped API middleware uses Express-specific
1955	   * req.method, req.path, req.headers, req.body, req.query, and res.setHeader /
1956	   * res.status / res.json / res.end. For Workers compatibility it must be
1957	   * rewritten as a Handler using ctx equivalents. Keep the existing Express
1958	   * code path.
1959	   */
1960	  router.use("/plugins/:pluginId/api", async (req, res) => {
1961	    if (!bridgeDeps) {
1962	      res.status(501).json({ error: "Plugin scoped API routes are not enabled" });
1963	      return;
1964	    }
1965	
1966	    const { pluginId } = req.params;
1967	    const plugin = await resolvePlugin(registry, pluginId);
1968	    if (!plugin) {
1969	      res.status(404).json({ error: "Plugin not found" });
1970	      return;
1971	    }
1972	    if (plugin.status !== "ready") {
1973	      res.status(503).json({ error: `Plugin is not ready (current status: ${plugin.status})` });
1974	      return;
1975	    }
1976	    const isWorkerRunning = typeof bridgeDeps.workerManager.isRunning === "function"
1977	      ? bridgeDeps.workerManager.isRunning(plugin.id)
1978	      : true;
1979	    if (!isWorkerRunning) {
1980	      res.status(503).json({ error: "Plugin worker is not running" });
1981	      return;
1982	    }
1983	    if (!plugin.manifestJson.capabilities.includes("api.routes.register")) {
1984	      res.status(404).json({ error: "Plugin does not expose scoped API routes" });
1985	      return;
1986	    }
1987	
1988	    const requestPath = req.path || "/";
1989	    const routes = plugin.manifestJson.apiRoutes ?? [];
1990	    const match = routes
1991	      .map((route) => ({ route, params: matchScopedApiRoute(route, req.method, requestPath) }))
1992	      .find((candidate) => candidate.params !== null);
1993	    if (!match || !match.params) {
1994	      res.status(404).json({ error: "Plugin API route not found" });
1995	      return;
1996	    }
1997	
1998	    try {
1999	      assertScopedApiAuth(req, match.route);
2000	      const companyId = await resolveScopedApiCompanyId(match.route, match.params, req);
2001	      if (!companyId) {
2002	        res.status(400).json({ error: "Unable to resolve company for plugin API route" });
2003	        return;
2004	      }
2005	      assertCompanyAccess(req, companyId);
2006	      await enforceScopedApiCheckout(req, match.route, match.params, companyId);
2007	      if (req.method !== "GET" && req.headers["content-type"] && !req.is("application/json")) {
2008	        res.status(415).json({ error: "Plugin API routes accept JSON requests only" });
2009	        return;
2010	      }
2011	      const requestBody = req.body ?? null;
2012	      const bodySize = Buffer.byteLength(JSON.stringify(requestBody));
2013	      if (bodySize > PLUGIN_API_BODY_LIMIT_BYTES) {
2014	        res.status(413).json({ error: "Plugin API request body is too large" });
2015	        return;
2016	      }
2017	
2018	      const actor = getActorInfo(req);
2019	      const input: PluginScopedApiRequest = {
2020	        routeKey: match.route.routeKey,
2021	        method: req.method,
2022	        path: requestPath,
2023	        params: match.params,
2024	        query: normalizeQuery(req.query),
2025	        body: requestBody,
2026	        actor: {
2027	          actorType: actor.actorType,
2028	          actorId: actor.actorId,
2029	          agentId: actor.agentId,
2030	          userId: actor.actorType === "user" ? actor.actorId : null,
2031	          runId: actor.runId,
2032	        },
2033	        companyId,
2034	        headers: sanitizePluginRequestHeaders(req),
2035	      };
2036	
2037	      const result = await bridgeDeps.workerManager.call(
2038	        plugin.id,
2039	        "handleApiRequest",
2040	        input,
2041	      ) as PluginScopedApiResponse;
2042	      const status = Number.isInteger(result.status) && Number(result.status) >= 200 && Number(result.status) <= 599
2043	        ? Number(result.status)
2044	        : 200;
2045	      applyPluginScopedApiResponseHeaders(res, result.headers);
2046	      if (status === 204) {
2047	        res.status(status).end();
2048	      } else {
2049	        res.status(status).json(result.body ?? null);
2050	      }
2051	    } catch (err) {
2052	      const status = typeof (err as { status?: unknown }).status === "number"
2053	        ? (err as { status: number }).status
2054	        : err instanceof JsonRpcCallError && err.code === PLUGIN_RPC_ERROR_CODES.CAPABILITY_DENIED
2055	          ? 403
2056	          : err instanceof JsonRpcCallError && err.code === PLUGIN_RPC_ERROR_CODES.METHOD_NOT_IMPLEMENTED
2057	            ? 501
2058	            : err instanceof JsonRpcCallError
2059	              ? 502
2060	              : 500;
2061	      res.status(status).json({
2062	        error: err instanceof Error ? err.message : String(err),
2063	      });
2064	    }
2065	  });
